@startuml

class Employee {
  + name : string
  + ssn : int
}

class CreativeEmployee extends Employee {
  + hasOscar : boolean
}

class Director extends CreativeEmployee {
  + assistantName : string
}

class Actor extends CreativeEmployee {
  + education : string
}

class Technician extends Employee {
  + fieldOfActivity : string
}

class Location {
  + name : string
}

class Film {
  + title : string
  + releaseYear : int
}

class Genre {
  thriller
  action
  horror
  comedy
}

class Screenwriter {
  + name : string
  + mostSuccessfulFilm : string
}

class Screenplay {
  + title : string
  + version : string
  + date : date
  + numberOfScenes : int
  + plot : string
}

class Novel {
  + title : string
}

class Author {
  + name : string
}

class Concept {
}

Film "1" -- "*" FilmSet : shot_at
FilmSet "*" -- "1" Location : located_at
Film "1" -- "1" Genre : has
Film "1" -- "1" Screenplay : based_on
Screenplay "1" -- "1" Film : written_for
Screenplay "*" -- "1" Screenwriter : created_by
Screenplay "1" -- "0..1" Novel : based_on
Screenplay "1" -- "0..1" Concept : based_on
Novel "*" -- "1" Author : written_by
Actor "*" -- "1" Screenplay : reads
Director "1" -- "1" Screenplay : implements

class FilmSet {}

@enduml

